from taf.gnb.oam.megazone_client import megazone_client
from taf.gnb.oam.megazone_client.exceptions import AlarmPresentException


try:
    import unittest2 as unittest
except ImportError:
    import unittest

try:
    from mock import Mock, patch
except ImportError:
    from unittest.mock import Mock, patch


@patch("taf.gnb.oam.megazone_client.alarms_endpoint.AlarmsEndpoint.get_active_faults_number", return_value=7)
@patch("taf.gnb.oam.megazone_client.alarms_endpoint.AlarmsEndpoint.get_historic_faults_number", return_value=11)
class TestBTSWithActiveAndHistoricFaults(unittest.TestCase):
    def setUp(self):
        self.cor = megazone_client()
        self.cor.session_handler = Mock()
        self.cor.session_store.add(Mock())

    def test_givenPositiveGetFaultsNumber_checkAllFaults_shouldFail(self, m_active_faults, m_historic_faults):
        with self.assertRaises(AlarmPresentException):
            self.cor.check_active_faults()

    def test_check_all_faults_when_allowing_negative_results_shouldPass(self, m_active_faults, m_historic_faults):
        self.cor.check_active_faults(allow_negative_result=True)
